<script setup>
import { ref, computed, watch, onMounted, onUnmounted, nextTick } from 'vue'
import { LayoutDashboard, Calculator, Layers3, Printer, Settings2, Plus, Trash2, ExternalLink, Download, Upload, Box, Zap, Clock3, TrendingUp, PoundSterling, ChevronRight, Info, Check, X, Sun, Moon, Monitor, ChevronLeft, Menu, Sparkles, HelpCircle, Package, BarChart3, ShoppingBag, ChevronDown, LogOut, Users, UserRound, ShieldCheck } from 'lucide-vue-next'

const initial = { settings:{currency:'GBP',siteTitle:'PrintQuote',siteSubtitle:'PRINT COST STUDIO',logo:'',accent:'#5277e8',background:'#f3f7ff',darkBackground:'#1b283d',themeMode:'auto',energyRate:0.28,labourRate:12,defaultMargin:30,onboardingCompleted:false,features:{dashboard:true,quotes:true,products:true,filaments:true,printers:true,sales:true,inventory:false}}, filaments:[], printers:[], quotes:[], products:[], sales:[] }
function clone(x){return JSON.parse(JSON.stringify(x))}
const state=ref(clone(initial))
const ready=ref(false), syncStatus=ref('Connecting…'), syncError=ref(false)
const systemDark=ref(window.matchMedia('(prefers-color-scheme: dark)').matches)
const media=window.matchMedia('(prefers-color-scheme: dark)')
const mediaListener=e=>{systemDark.value=e.matches}
const isDark=computed(()=>state.value.settings.themeMode==='dark'||(state.value.settings.themeMode==='auto'&&systemDark.value))
const theme=computed(()=>({ '--accent':state.value.settings.accent||'#6478f5','--surface':isDark.value?(state.value.settings.darkBackground||'#101827'):(state.value.settings.background||'#f7f9ff'), }))
function cycleTheme(){const modes=['auto','light','dark'];state.value.settings.themeMode=modes[(modes.indexOf(state.value.settings.themeMode)+1)%3]}
const themeLabel=computed(()=>({auto:'Auto theme',light:'Light theme',dark:'Dark theme'})[state.value.settings.themeMode]||'Auto theme')
let timer=null, saving=false, dirty=false, generation=0
const authUser=ref(null),authReady=ref(false),authToken=ref(localStorage.getItem('pq_token')||sessionStorage.getItem('pq_token')||'')
const loginDraft=ref({username:'',password:'',remember:false}),loginError=ref(''),loginBusy=ref(false)
const accountMenu=ref(false),adminUsers=ref([]),adminError=ref(''),adminDraft=ref({username:'',firstName:'',lastName:'',password:''})
const passwordDraft=ref({currentPassword:'',newPassword:''}),passwordError=ref('')
const initials=computed(()=>[authUser.value?.firstName,authUser.value?.lastName].map(x=>String(x||'').trim().slice(0,1)).join('').toUpperCase()||'U')
function storeToken(token,remember){authToken.value=token;localStorage.removeItem('pq_token');sessionStorage.removeItem('pq_token');(remember?localStorage:sessionStorage).setItem('pq_token',token)}
function logoutLocal(){authToken.value='';authUser.value=null;ready.value=false;authReady.value=true;accountMenu.value=false;localStorage.removeItem('pq_token');sessionStorage.removeItem('pq_token');clearTimeout(timer);dirty=false}
async function api(url,options={}){const res=await fetch(url,{...options,headers:{'Content-Type':'application/json',...(authToken.value?{Authorization:'Bearer '+authToken.value}:{}),...options.headers}});if(res.status===401&&url!=='/api/auth/login'){logoutLocal();throw Error('Session expired')}const body=await res.json().catch(()=>({}));if(!res.ok)throw Error(body.error||`Server returned ${res.status}`);return body}
async function checkAuth(){try{if(authToken.value){const data=await api('/api/auth/me');authUser.value=data.user;await refresh()}}catch(e){logoutLocal()}finally{authReady.value=true}}
async function login(){loginError.value='';loginBusy.value=true;try{const data=await api('/api/auth/login',{method:'POST',body:JSON.stringify(loginDraft.value)});storeToken(data.token,loginDraft.value.remember);authUser.value=data.user;loginDraft.value.password='';await refresh()}catch(e){loginError.value=e.message}finally{loginBusy.value=false}}
async function logout(){try{await api('/api/auth/logout',{method:'POST'})}catch{}logoutLocal()}
async function loadUsers(){adminError.value='';try{adminUsers.value=(await api('/api/admin/users')).users}catch(e){adminError.value=e.message}}
async function createUser(){adminError.value='';try{await api('/api/admin/users',{method:'POST',body:JSON.stringify(adminDraft.value)});adminDraft.value={username:'',firstName:'',lastName:'',password:''};await loadUsers();toast('User created')}catch(e){adminError.value=e.message}}
async function deleteUser(user){if(!confirm('Delete '+user.username+'? Their active sessions will be revoked.'))return;try{await api('/api/admin/users/'+user.id,{method:'DELETE'});await loadUsers()}catch(e){adminError.value=e.message}}
async function changePassword(){passwordError.value='';try{await api('/api/auth/password',{method:'POST',body:JSON.stringify(passwordDraft.value)});passwordDraft.value={currentPassword:'',newPassword:''};authUser.value={...authUser.value,mustChangePassword:false};toast('Password updated. Please sign in again.');logoutLocal()}catch(e){passwordError.value=e.message}}
async function refresh(){try{const data=await api('/api/state');if(!Array.isArray(data.filaments)||!Array.isArray(data.printers))throw Error('Invalid database state');state.value={...clone(initial),...data,products:Array.isArray(data.products)?data.products:[],sales:Array.isArray(data.sales)?data.sales:[],settings:{...initial.settings,...data.settings,onboardingCompleted:data.settings?.onboardingCompleted ?? true,features:{...initial.settings.features,...data.settings?.features}}};ready.value=true; if(!state.value.settings.onboardingCompleted) startTour();syncError.value=false;syncStatus.value='Database connected'}catch(e){syncError.value=true;syncStatus.value='Database unavailable';console.error(e)}}
async function flush(){if(!ready.value||saving)return;saving=true;while(dirty){dirty=false;const payload=JSON.stringify(state.value);syncStatus.value='Saving…';try{await api('/api/state',{method:'PUT',body:payload});syncStatus.value='Saved to database';syncError.value=false}catch(e){dirty=true;syncError.value=true;syncStatus.value='Save failed — retrying';console.error(e);break}}saving=false;if(dirty){clearTimeout(timer);timer=setTimeout(flush,3000)}}
watch(state,()=>{if(!ready.value)return;dirty=true;syncStatus.value='Unsaved changes';clearTimeout(timer);timer=setTimeout(flush,650)},{deep:true})
onMounted(()=>{media.addEventListener('change',mediaListener);window.addEventListener('resize',positionTour);window.addEventListener('scroll',positionTour,true);checkAuth()})
onUnmounted(()=>{media.removeEventListener('change',mediaListener);window.removeEventListener('resize',positionTour);window.removeEventListener('scroll',positionTour,true);clearTimeout(timer)})
const logoInput=ref(null)
function uploadLogo(e){const f=e.target.files?.[0];if(!f)return;if(!f.type.startsWith('image/')){toast('Please select an image');return}if(f.size>1024*1024){toast('Logo must be smaller than 1 MB');return}const reader=new FileReader();reader.onload=()=>{state.value.settings.logo=String(reader.result);toast('Logo updated')};reader.readAsDataURL(f);e.target.value=''}

const page=ref('calculator'), mobileMenu=ref(false), sidebarCollapsed=ref(false), notification=ref('')
function toast(t){notification.value=t;setTimeout(()=>notification.value='',3000)}
const uid=()=>Math.random().toString(36).slice(2,10)
const money=v=>new Intl.NumberFormat('en-GB',{style:'currency',currency:state.value.settings.currency||'GBP'}).format(Number(v)||0)
const num=(v)=>Math.max(0,Number(v)||0)
const quote=ref({name:'',filamentId:'',printerId:'',grams:120,hours:4,minutes:30,quantity:1,margin:30,extraCost:0,setupOverride:false})
const filament=computed(()=>state.value.filaments.find(f=>f.id===quote.value.filamentId))
const printer=computed(()=>state.value.printers.find(p=>p.id===quote.value.printerId))
const calc=computed(()=>{const q=quote.value,p=printer.value;const qty=Math.max(1,Math.floor(Number(q.quantity)||1));const hours=num(q.hours)+num(q.minutes)/60;const material=num(q.grams)/1000*num(filament.value?.price)*qty;const energy=hours*num(p?.power)/1000*num(state.value.settings.energyRate)*qty;const labour=(num(p?.setupMinutes)+num(p?.postMinutes)*qty)/60*num(state.value.settings.labourRate);const overhead=hours*num(p?.overheadRate)*qty;const extras=num(q.extraCost)*qty;const cost=material+energy+labour+overhead+extras;const margin=Math.min(99.9,num(q.margin));const price=cost/(1-margin/100);const profit=price-cost;return {qty,hours,material,energy,labour,overhead,extras,cost,price,profit,margin,markup:cost?profit/cost*100:0,unit:price/qty}})
const saveMenu=ref(false), saleProduct=ref(null), saleDraft=ref({quantity:1,unitPrice:0,date:new Date().toISOString().slice(0,10),note:''})
const extraItems=ref([])
function unitCostFor(p){
 const f=state.value.filaments.find(x=>x.id===p.filamentId),r=state.value.printers.find(x=>x.id===p.printerId)
 if(!f||!r)return null
 const hours=num(p.hours)+num(p.minutes)/60
 return num(p.grams)/1000*num(f.price)+hours*num(r.power)/1000*num(state.value.settings.energyRate)+(num(r.setupMinutes)+num(r.postMinutes))/60*num(state.value.settings.labourRate)+hours*num(r.overheadRate)+num(p.extraCost)
}
const productCost=p=>unitCostFor(p)
const productMargin=p=>{const cost=productCost(p);return cost===null||!num(p.price)?null:(num(p.price)-cost)/num(p.price)*100}
function addQuoteProduct(p){const cost=productCost(p);if(cost===null){toast('Assign a valid filament and printer to this product');return}extraItems.value.push({id:uid(),productId:p.id,name:p.name,quantity:1,unitPrice:num(p.price),unitCost:cost});page.value='calculator';toast('Product added to quote')}
function addSelectedProduct(){const select=document.getElementById('quote-product-select');const p=state.value.products.find(x=>x.id===select?.value);if(!p){toast('Select a product first');return}addQuoteProduct(p);select.value=''}
function removeSale(id){if(!confirm('Delete this recorded sale?'))return;state.value.sales=state.value.sales.filter(s=>s.id!==id)}
function removeQuoteItem(id){extraItems.value=extraItems.value.filter(x=>x.id!==id)}
const extraTotal=computed(()=>extraItems.value.reduce((sum,x)=>sum+num(x.unitPrice)*Math.max(1,Math.floor(num(x.quantity))),0))
const extraCostTotal=computed(()=>extraItems.value.reduce((sum,x)=>sum+num(x.unitCost)*Math.max(1,Math.floor(num(x.quantity))),0))
const quoteGrandTotal=computed(()=>calc.value.price+extraTotal.value)
const quoteGrandCost=computed(()=>calc.value.cost+extraCostTotal.value)
function productFromCalculator(){if(!filament.value||!printer.value){toast('Select a printer and filament first');return}newProduct();editingProduct.value.name=quote.value.name||'';editingProduct.value.price=Number(calc.value.unit.toFixed(2));saveMenu.value=false}
function beginSale(p){saleProduct.value=p;saleDraft.value={quantity:1,unitPrice:num(p.price),date:new Date().toISOString().slice(0,10),note:''}}
function recordSale(){if(!saleProduct.value)return;const quantity=Math.floor(Number(saleDraft.value.quantity));const price=Number(saleDraft.value.unitPrice);if(!Number.isInteger(quantity)||quantity<1||!Number.isFinite(price)||price<0||!/^\d{4}-\d{2}-\d{2}$/.test(saleDraft.value.date)){toast('Enter a valid quantity, price and date');return}
 const cost=productCost(saleProduct.value);state.value.sales.unshift({id:uid(),productId:saleProduct.value.id,productName:saleProduct.value.name,quantity,unitPrice:price,unitCost:cost,date:saleDraft.value.date,note:saleDraft.value.note||''});saleProduct.value=null;toast('Sale recorded')}
const salesSummary=computed(()=>{const sales=state.value.sales||[];return {count:sales.reduce((a,x)=>a+num(x.quantity),0),revenue:sales.reduce((a,x)=>a+num(x.quantity)*num(x.unitPrice),0),profit:sales.reduce((a,x)=>a+num(x.quantity)*(num(x.unitPrice)-num(x.unitCost)),0)}})
const productSales=p=>state.value.sales.filter(x=>x.productId===p.id)
const productUnits=p=>productSales(p).reduce((a,x)=>a+num(x.quantity),0)
const ranking=computed(()=>state.value.products.map(p=>({...p,units:productUnits(p),revenue:productSales(p).reduce((a,x)=>a+num(x.quantity)*num(x.unitPrice),0)})).sort((a,b)=>b.units-a.units))
const recentSales=computed(()=>[...state.value.sales].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,6))
const monthlyTrend=computed(()=>{const today=new Date();const months=Array.from({length:6},(_,i)=>{const d=new Date(today.getFullYear(),today.getMonth()-5+i,1);return {key:d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0'),label:d.toLocaleDateString('en-GB',{month:'short'}),revenue:0,units:0}});for(const sale of state.value.sales){const m=months.find(x=>x.key===String(sale.date).slice(0,7));if(m){m.revenue+=num(sale.unitPrice)*num(sale.quantity);m.units+=num(sale.quantity)}}return months})
const trendMax=computed(()=>Math.max(1,...monthlyTrend.value.map(x=>x.revenue)))
const forecast=computed(()=>{const past=monthlyTrend.value.slice(0,5);const nonzero=past.filter(x=>x.units>0);if(nonzero.length<2)return null;const avg=nonzero.reduce((a,x)=>a+x.units,0)/nonzero.length;const recent=monthlyTrend.value.slice(-3,-1).reduce((a,x)=>a+x.units,0)/2;return Math.max(0,Math.round((avg+recent)/2))})
const editingFilament=ref(null),editingPrinter=ref(null)
function newFilament(){if(tourActive.value&&tourStep.value===1) nextTour();editingFilament.value={id:uid(),name:'',brand:'',material:'PLA',colour:'',price:20,url:'',stockGrams:0,lowStockGrams:150}}
function editFilament(f){editingFilament.value=clone(f)}
function saveFilament(){const f=editingFilament.value;if(!f.name.trim()){toast('Please enter a filament name');return}if(f.url && !/^https?:\/\//i.test(f.url)){toast('Purchase link must start with http:// or https://');return}f.price=num(f.price);f.stockGrams=num(f.stockGrams);f.lowStockGrams=num(f.lowStockGrams);const idx=state.value.filaments.findIndex(x=>x.id===f.id);if(idx<0)state.value.filaments.push(f);else state.value.filaments[idx]=f;if(!quote.value.filamentId)quote.value.filamentId=f.id;editingFilament.value=null;toast('Filament saved')}
function removeFilament(id){if(!confirm('Delete this filament?'))return;state.value.filaments=state.value.filaments.filter(f=>f.id!==id);if(quote.value.filamentId===id)quote.value.filamentId=state.value.filaments[0]?.id||''}
function newPrinter(){if(tourActive.value&&tourStep.value===3) nextTour();editingPrinter.value={id:uid(),name:'',technology:'FDM',power:100,setupMinutes:10,postMinutes:10,overheadRate:0.25}}
function editPrinter(p){editingPrinter.value=clone(p)}
function savePrinter(){const p=editingPrinter.value;if(!p.name.trim()){toast('Please enter a printer name');return}for(const k of ['power','setupMinutes','postMinutes','overheadRate'])p[k]=num(p[k]);const idx=state.value.printers.findIndex(x=>x.id===p.id);if(idx<0)state.value.printers.push(p);else state.value.printers[idx]=p;if(!quote.value.printerId)quote.value.printerId=p.id;editingPrinter.value=null;toast('Printer saved')}
function removePrinter(id){if(!confirm('Delete this printer profile?'))return;state.value.printers=state.value.printers.filter(p=>p.id!==id);if(quote.value.printerId===id)quote.value.printerId=state.value.printers[0]?.id||''}
function saveQuote(){if(!filament.value||!printer.value){toast('Add a filament and printer first');return}state.value.quotes.unshift({id:uid(),name:quote.value.name.trim()||'Untitled print',date:new Date().toISOString(),filament:filament.value.name,printer:printer.value.name,details:clone(quote.value),items:clone(extraItems.value),result:{...clone(calc.value),cost:quoteGrandCost.value,price:quoteGrandTotal.value,profit:quoteGrandTotal.value-quoteGrandCost.value}});saveMenu.value=false;toast('Quote saved — prices locked to this estimate')}
function loadQuote(q){quote.value={...quote.value,...clone(q.details)};extraItems.value=clone(q.items||[]);page.value='calculator';toast('Quote loaded — review current pricing before saving again')}
const editingProduct=ref(null)
function newProduct(){editingProduct.value={id:uid(),name:'',description:'',customer:'',sku:'',status:'Active',filamentId:quote.value.filamentId||'',printerId:quote.value.printerId||'',grams:num(quote.value.grams),hours:num(quote.value.hours),minutes:num(quote.value.minutes),price:Number(calc.value.price.toFixed(2)),notes:''}}
function productFromQuote(q){const d=q.details||{};editingProduct.value={id:uid(),name:q.name||'',description:'',customer:'',sku:'',status:'Active',filamentId:d.filamentId||'',printerId:d.printerId||'',grams:num(d.grams),hours:num(d.hours),minutes:num(d.minutes),price:Number(q.result?.price||0),notes:''};page.value=enabled('products')?'products':'calculator'}
function saveProduct(){const item=editingProduct.value;if(!item.name.trim()){toast('Enter a product name');return}item.grams=num(item.grams);item.hours=num(item.hours);item.minutes=num(item.minutes);item.price=num(item.price);const i=state.value.products.findIndex(p=>p.id===item.id);if(i<0)state.value.products.unshift(clone(item));else state.value.products[i]=clone(item);editingProduct.value=null;toast('Product saved')}
function removeProduct(id){if(!confirm('Delete this saved product?'))return;state.value.products=state.value.products.filter(p=>p.id!==id)}
function loadProduct(p){quote.value={...quote.value,name:p.name,filamentId:p.filamentId,printerId:p.printerId,grams:p.grams,hours:p.hours,minutes:p.minutes,quantity:1};extraItems.value=[];page.value='calculator';toast('Product loaded — live production costs applied')}
function removeQuote(id){state.value.quotes=state.value.quotes.filter(q=>q.id!==id)}
function exportData(){const blob=new Blob([JSON.stringify(state.value,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='printquote-backup.json';a.click();URL.revokeObjectURL(url);toast('Backup downloaded')}
const fileInput=ref(null)
async function importData(e){const f=e.target.files?.[0];if(!f)return;try{const data=JSON.parse(await f.text());if(!Array.isArray(data.filaments)||!Array.isArray(data.printers)||!data.settings)throw Error('Invalid backup');if(!confirm('Replace your current data with this backup?'))return;state.value={...clone(initial),...data,sales:Array.isArray(data.sales)?data.sales:[],products:Array.isArray(data.products)?data.products:[]};quote.value.filamentId=state.value.filaments[0]?.id||'';quote.value.printerId=state.value.printers[0]?.id||'';toast('Backup restored')}catch{toast('Could not read backup file')}finally{e.target.value=''}}
const navItems=[{id:'dashboard',label:'Dashboard',icon:BarChart3},{id:'calculator',label:'Cost calculator',icon:Calculator},{id:'history',label:'Saved quotes',icon:LayoutDashboard},{id:'products',label:'Products',icon:Package},{id:'filaments',label:'Filament library',icon:Layers3},{id:'printers',label:'Printer profiles',icon:Printer}]
const features=computed(()=>({...initial.settings.features,...state.value.settings.features}))
const enabled=id=>id==='calculator'||id==='settings'||(id==='history'?features.value.quotes:features.value[id]!==false)
const nav=computed(()=>navItems.filter(n=>enabled(n.id)))
const presets={simple:{dashboard:false,quotes:false,products:false,filaments:true,printers:true,sales:false,inventory:false},pricing:{dashboard:false,quotes:true,products:true,filaments:true,printers:true,sales:false,inventory:false},full:{dashboard:true,quotes:true,products:true,filaments:true,printers:true,sales:true,inventory:true}}
function applyPreset(key){state.value.settings.features={...presets[key]};toast('Workspace preset applied')}
function toggleFeature(key){state.value.settings.features={...features.value,[key]:!features.value[key]}}
watch(features,()=>{if(!enabled(page.value))page.value='calculator';if(!features.value.sales)saleProduct.value=null;if(!features.value.quotes)saveMenu.value=false},{deep:true})
function navigate(id){if(!enabled(id))return;page.value=id;mobileMenu.value=false;if(tourActive.value){if(tourStep.value===0&&id==='filaments')nextTour();else if(tourStep.value===2&&id==='printers')nextTour();else if(tourStep.value===4&&id==='settings')nextTour();else if(tourStep.value===5&&id==='calculator')finishTour()}}
const pageTitle=computed(()=>page.value==='administration'?'Administration':nav.value.find(n=>n.id===page.value)?.label||'Calculator')

// Shared first-run guide: completion is persisted in the server-side SQLite state.
const tourActive=ref(false),tourStep=ref(0)
const tourPosition=ref({top:'90px',left:'300px'})
let tourObserver=null
function positionTour(){
  if(!tourActive.value)return
  const target=document.querySelector(`[data-tour="${tourCurrent.value.target}"]`)
  if(!target)return
  const r=target.getBoundingClientRect(), width=Math.min(390,window.innerWidth-24), height=285, gap=18
  let left=r.right+gap
  if(left+width>window.innerWidth-12)left=r.left-width-gap
  if(left<12)left=Math.max(12,Math.min(window.innerWidth-width-12,r.left))
  let top=r.top
  if(top+height>window.innerHeight-12)top=Math.max(12,window.innerHeight-height-12)
  tourPosition.value={top:`${Math.round(top)}px`,left:`${Math.round(left)}px`}
}
watch([tourActive,tourStep,page,mobileMenu],async()=>{await nextTick();positionTour()},{flush:'post'})

const tourSteps=[
  {title:'Your filament library',body:'Start here. Click Filament library in the sidebar to open your material catalogue.',target:'tour-filaments'},
  {title:'Add your first filament',body:'Click Add filament. Enter its name, material and price per kilogram. You can close the editor whenever you like.',target:'tour-add-filament'},
  {title:'Your printer profiles',body:'Next, click Printer profiles in the sidebar to set up your machine.',target:'tour-printers'},
  {title:'Add your printer',body:'Click Add printer to set its wattage, setup time, finishing time and hourly overhead.',target:'tour-add-printer'},
  {title:'Business settings',body:'Click Settings at the bottom of the sidebar to enter your electricity rate, labour rate and branding.',target:'tour-settings'},
  {title:'Make your first quote',body:'Head back to Cost calculator. Select a filament and printer, enter print time and material used, and see your costs instantly.',target:'tour-calculator'}
]
const tourCurrent=computed(()=>tourSteps[tourStep.value]||tourSteps[0])
function startTour(){if(!features.value.filaments||!features.value.printers){toast('Enable Filaments and Printers in Settings to use the guided tour');return}editingFilament.value=null;editingPrinter.value=null;page.value='calculator';tourStep.value=0;tourActive.value=true;sidebarCollapsed.value=false;mobileMenu.value=false}
function nextTour(){tourStep.value=Math.min(tourStep.value+1,tourSteps.length-1);editingFilament.value=null;editingPrinter.value=null;sidebarCollapsed.value=false;const destinations=['filaments','filaments','printers','printers','settings','calculator'];page.value=destinations[tourStep.value]}
function finishTour(){tourActive.value=false;state.value.settings.onboardingCompleted=true;toast('You’re all set! Happy printing ✨')}
function skipTour(){finishTour()}

</script>

<template>
<div v-if="!authReady" class="auth-screen"><div class="auth-card"><h1>PrintQuote</h1><p>Checking your session…</p></div></div>
<div v-else-if="!authUser" class="auth-screen"><form class="auth-card" @submit.prevent="login"><div class="auth-logo"><Box :size="28"/></div><h1>Welcome to PrintQuote</h1><p>Sign in to your workspace</p><label>Username<input v-model.trim="loginDraft.username" required autocomplete="username" autofocus/></label><label>Password<input v-model="loginDraft.password" type="password" required autocomplete="current-password"/></label><label class="remember"><input v-model="loginDraft.remember" type="checkbox"/> Remember me on this device</label><p v-if="loginError" class="auth-error" role="alert">{{loginError}}</p><button class="btn primary" type="submit" :disabled="loginBusy">{{loginBusy?'Signing in…':'Sign in'}}</button></form></div>
<div v-else class="shell" :class="{'dark-mode':isDark,'sidebar-collapsed':sidebarCollapsed,'tour-running':tourActive}" :data-tour-step="tourActive?tourCurrent.target:null" :style="theme">
  <aside class="sidebar" :class="{open:mobileMenu}">
    <div class="brand"><div class="brand-icon"><img v-if="state.settings.logo" :src="state.settings.logo" alt="Site logo"/><Box v-else :size="23" :stroke-width="2.5"/></div><div><strong>{{state.settings.siteTitle||'PrintQuote'}}<span>.</span></strong><small>{{state.settings.siteSubtitle||'PRINT COST STUDIO'}}</small></div></div>
    <button class="sidebar-collapse" type="button" @click="sidebarCollapsed=!sidebarCollapsed" :title="sidebarCollapsed?'Expand sidebar':'Collapse sidebar'" :aria-label="sidebarCollapsed?'Expand sidebar':'Collapse sidebar'"><ChevronRight v-if="sidebarCollapsed" :size="17"/><ChevronLeft v-else :size="17"/></button>
    <nav><button v-for="n in nav" :key="n.id" :title="n.label" :data-tour="'tour-'+n.id" :class="['nav-link',{active:page===n.id}]" @click="navigate(n.id)"><component :is="n.icon" :size="18"/><span>{{n.label}}</span><ChevronRight class="chev" :size="15"/></button></nav>
    <div class="sidebar-footer"><button class="sidebar-settings" data-tour="tour-settings" :class="{active:page==='settings'}" type="button" @click="navigate('settings')" title="Settings"><Settings2 :size="18"/><span>Settings</span></button></div>
  </aside>
  <div v-if="mobileMenu" class="mobile-overlay" @click="mobileMenu=false"></div>
  <main class="main">
    <header class="topbar"><button class="mobile-toggle" type="button" @click="mobileMenu=!mobileMenu" aria-label="Open navigation"><Menu :size="21"/></button><div class="breadcrumb">Workspace <ChevronRight :size="14"/> <b>{{pageTitle}}</b></div><div class="top-right"><button v-if="features.filaments && features.printers" class="tour-replay" type="button" @click="startTour" title="Show the guided tour" aria-label="Show guided tour"><HelpCircle :size="18"/></button><button class="theme-toggle" type="button" @click="cycleTheme" :title="themeLabel" :aria-label="themeLabel"><Monitor v-if="state.settings.themeMode==='auto'" :size="17"/><Sun v-else-if="state.settings.themeMode==='light'" :size="17"/><Moon v-else :size="17"/><span>{{state.settings.themeMode}}</span></button><div class="account-wrap"><button class="avatar account-trigger" type="button" @click="accountMenu=!accountMenu" :aria-expanded="accountMenu" aria-label="Account menu">{{initials}}</button><div v-if="accountMenu" class="account-dropdown"><strong>{{authUser.firstName}} {{authUser.lastName}}</strong><small>@{{authUser.username}} · {{authUser.role}}</small><button v-if="authUser.role==='admin'" type="button" @click="page='administration';loadUsers();accountMenu=false"><Users :size="16"/> Administration</button><button type="button" @click="page='account';accountMenu=false"><UserRound :size="16"/> My account</button><button type="button" @click="logout"><LogOut :size="16"/> Sign out</button></div></div></div></header>
    <div class="content"><div v-if="authUser.mustChangePassword" class="db-warning">You're using the initial admin password. Please change it under My account before publishing this site.</div>
<div v-if="page==='account'"><div class="page-head"><div><h1>My account</h1><p>{{authUser.firstName}} {{authUser.lastName}} · @{{authUser.username}}</p></div></div><section class="card auth-management"><h2>Change password</h2><p>Use at least 6 characters, one number and one special character.</p><form @submit.prevent="changePassword"><label>Current password<input type="password" v-model="passwordDraft.currentPassword" required autocomplete="current-password"/></label><label>New password<input type="password" v-model="passwordDraft.newPassword" minlength="6" required autocomplete="new-password"/></label><p v-if="passwordError" class="auth-error">{{passwordError}}</p><button class="btn primary" type="submit">Change password</button></form></section></div>
<div v-if="page==='administration' && authUser.role==='admin'"><div class="page-head"><div><h1>Administration</h1><p>Manage who can access this PrintQuote workspace.</p></div></div><section class="card auth-management"><h2>Add user</h2><p>Passwords require 6+ characters, at least one number and one special character.</p><form @submit.prevent="createUser"><label>Username<input v-model.trim="adminDraft.username" required minlength="3" autocomplete="off"/></label><label>First name<input v-model.trim="adminDraft.firstName" required/></label><label>Last name<input v-model.trim="adminDraft.lastName" required/></label><label>Initial password<input type="password" v-model="adminDraft.password" required minlength="6" autocomplete="new-password"/></label><p v-if="adminError" class="auth-error">{{adminError}}</p><button type="submit" class="btn primary"><Plus :size="16"/> Add user</button></form></section><section class="card auth-management"><h2>Users</h2><div v-for="u in adminUsers" :key="u.id" class="auth-user-row"><span><strong>{{u.firstName}} {{u.lastName}}</strong><small>@{{u.username}} · {{u.role}}</small></span><button v-if="u.id!==authUser.id" class="btn small" @click="deleteUser(u)">Remove</button></div></section></div>
<div v-if="!ready" class="db-warning">Cannot load the shared workspace. Check the application API container and refresh the page. No local changes will be saved until the connection succeeds.</div>
      <div v-if="page==='dashboard' && features.dashboard" class="dashboard-page">
 <div class="page-head"><div><div class="eyebrow">YOUR WORKSPACE</div><h1>Dashboard</h1><p>Your printing costs, best sellers and recent sales at a glance.</p></div><button class="btn primary" @click="navigate('calculator')"><Calculator :size="17"/> New estimate</button></div>
 <div v-if="!features.sales" class="stats-grid"><div class="stat"><div class="stat-top">Saved products <Package :size="19"/></div><div class="stat-value">{{state.products.length}}</div><small>Your reusable designs</small></div><div class="stat"><div class="stat-top">Saved quotes <LayoutDashboard :size="19"/></div><div class="stat-value">{{state.quotes.length}}</div><small>Stored estimates</small></div><div class="stat"><div class="stat-top">Materials <Layers3 :size="19"/></div><div class="stat-value">{{state.filaments.length}}</div><small>Filament profiles</small></div></div><div v-if="features.sales" class="stats-grid"><div class="stat"><div class="stat-top">Sales revenue <ShoppingBag :size="19"/></div><div class="stat-value">{{money(salesSummary.revenue)}}</div><small>Recorded sales</small></div><div class="stat"><div class="stat-top">Estimated gross profit <TrendingUp :size="19"/></div><div class="stat-value profit">{{money(salesSummary.profit)}}</div><small>Based on costs when each sale was logged</small></div><div class="stat"><div class="stat-top">Items sold <Package :size="19"/></div><div class="stat-value">{{salesSummary.count}}</div><small>{{state.products.length}} saved products · {{state.quotes.length}} quotes</small></div></div>
 <div v-if="features.sales" class="dashboard-columns"><section class="card"><div class="card-heading"><div><h2>Revenue over time</h2><p>Last six calendar months · recorded sales only</p></div><BarChart3 :size="20"/></div><div class="sales-chart"><div v-for="month in monthlyTrend" :key="month.key" class="sales-bar-col"><strong>{{money(month.revenue)}}</strong><div class="sales-bar-track"><div class="sales-bar" :style="{height:Math.max(month.revenue?6:0,month.revenue/trendMax*100)+'%'}"></div></div><span>{{month.label}}</span></div></div><div class="info-box"><Info :size="16"/>{{forecast===null?'Add sales across at least two previous months to unlock a basic demand estimate.':'Indicative next-month demand: around '+forecast+' items, based on recent recorded months. Not a guarantee or market-wide forecast.'}}</div></section>
 <section class="card"><div class="card-heading"><div><h2>Most popular products</h2><p>Ranked by units sold</p></div><Package :size="20"/></div><div v-if="!ranking.length" class="empty">Save a product to see it here.</div><div v-for="(p,i) in ranking.slice(0,6)" :key="p.id" class="ranking-row"><span class="ranking-index">{{i+1}}</span><div><strong>{{p.name}}</strong><small>{{p.units}} sold · {{money(p.revenue)}} revenue</small></div><button v-if="features.sales" class="btn small" @click="beginSale(p)">+ Sale</button></div></section></div>
 <section v-if="features.inventory" class="card inventory-summary"><div class="card-heading"><div><h2>Filament stock</h2><p>Manual stock balances · low-stock reminders</p></div></div><div v-for="f in state.filaments" :key="f.id" class="stock-row"><strong>{{f.name}}</strong><span :class="{'stock-low':num(f.stockGrams)<=num(f.lowStockGrams)}">{{num(f.stockGrams)}}g remaining</span></div><p v-if="!state.filaments.length" class="muted">Add filament profiles to track stock.</p></section><section v-if="features.sales" class="card recent-sales"><div class="card-heading"><div><h2>Recent sales</h2><p>Actual recorded sales, not quotes</p></div></div><div class="table-wrap"><table><thead><tr><th>DATE</th><th>PRODUCT</th><th>QTY</th><th>REVENUE</th><th></th></tr></thead><tbody><tr v-for="sale in recentSales" :key="sale.id"><td>{{sale.date}}</td><td>{{sale.productName}}</td><td>{{sale.quantity}}</td><td class="bold">{{money(sale.quantity*sale.unitPrice)}}</td><td><button class="icon-button danger" title="Delete sale" @click="removeSale(sale.id)"><Trash2 :size="15"/></button></td></tr><tr v-if="!recentSales.length"><td colspan="5" class="empty">No sales recorded yet. Open Products and select Record sale to begin.</td></tr></tbody></table></div></section>
 </div>
 <div v-if="page==='calculator'">
        <div class="page-head"><div><div class="eyebrow">ESTIMATE & QUOTE</div><h1>Print cost calculator</h1><p>Know your costs. Price every print with confidence.</p></div><div v-if="features.quotes || features.products" class="save-actions"><button v-if="features.quotes" class="btn primary" @click="saveQuote"><Plus :size="17"/> Save quote</button><div v-if="features.products" class="save-dropdown"><button class="btn save-chevron" aria-label="More save options" :aria-expanded="saveMenu" @click="saveMenu=!saveMenu"><ChevronDown :size="18"/></button><div v-if="saveMenu" class="save-dropdown-menu"><button @click="productFromCalculator"><Package :size="16"/> Save as product</button></div></div></div></div>
        <div class="stats-grid">
          <div class="stat"><div class="stat-top"><span>Total production cost</span><div class="mini-icon violet"><PoundSterling :size="17"/></div></div><div class="stat-value">{{money(calc.cost)}}</div><small>All costs included</small></div>
          <div class="stat"><div class="stat-top"><span>Suggested selling price</span><div class="mini-icon blue"><Calculator :size="17"/></div></div><div class="stat-value">{{money(calc.price)}}</div><small>{{calc.margin}}% profit margin</small></div>
          <div class="stat"><div class="stat-top"><span>Estimated profit</span><div class="mini-icon green"><TrendingUp :size="17"/></div></div><div class="stat-value profit">{{money(calc.profit)}}</div><small>{{money(calc.unit)}} per item selling price</small></div>
        </div>
        <div v-if="features.quotes && features.products" class="card quote-products"><div class="card-heading"><div><h2>Products in this quote</h2><p>Add saved products as extra line items. Their selling prices are captured when you save.</p></div></div><div class="quote-picker"><select aria-label="Choose saved product" id="quote-product-select"><option value="">Select a saved product…</option><option v-for="p in state.products" :key="p.id" :value="p.id">{{p.name}} — {{money(p.price)}}</option></select><button class="btn" @click="addSelectedProduct">Add to quote</button></div><div v-for="item in extraItems" :key="item.id" class="quote-line"><strong>{{item.name}}</strong><label>Quantity <input type="number" min="1" step="1" v-model.number="item.quantity"/></label><span>{{money(item.unitPrice)}} each</span><button class="icon-button danger" @click="removeQuoteItem(item.id)" title="Remove line"><Trash2 :size="16"/></button></div><div v-if="extraItems.length" class="quote-line-total"><strong>Quote total (calculator + saved products)</strong><strong>{{money(quoteGrandTotal)}}</strong></div></div>
        <div class="two-col">
          <section class="card"><div class="card-heading"><div><h2>Print details</h2><p>Enter your slicer estimates and select materials.</p></div><div class="card-badge">01 / INPUT</div></div>
            <div class="field"><label>Project name <span>Optional</span></label><input v-model="quote.name" placeholder="e.g. Custom phone stand"/></div>
            <div class="field-grid"><div class="field"><label>Printer model</label><select v-model="quote.printerId"><option disabled value="">Select printer</option><option v-for="p in state.printers" :value="p.id" :key="p.id">{{p.name}}</option></select></div><div class="field"><label>Filament</label><select v-model="quote.filamentId"><option disabled value="">Select filament</option><option v-for="f in state.filaments" :value="f.id" :key="f.id">{{f.brand ? f.brand+' · ' : ''}}{{f.name}}</option></select></div></div>
            <div class="field-grid"><div class="field"><label>Filament used <span>grams / item</span></label><div class="input-unit"><input type="number" min="0" step="0.1" v-model.number="quote.grams"/><span>g</span></div></div><div class="field"><label>Quantity</label><div class="input-unit"><input type="number" min="1" step="1" v-model.number="quote.quantity"/><span>pcs</span></div></div></div>
            <div class="field"><label>Print duration <span>per item</span></label><div class="field-grid"><div class="input-unit"><input type="number" min="0" step="1" v-model.number="quote.hours"/><span>hours</span></div><div class="input-unit"><input type="number" min="0" max="59" step="1" v-model.number="quote.minutes"/><span>min</span></div></div></div>
            <div class="field-grid"><div class="field"><label>Target profit margin</label><div class="input-unit"><input type="number" min="0" max="99.9" step="1" v-model.number="quote.margin"/><span>%</span></div></div><div class="field"><label>Extra cost <span>per item</span></label><div class="input-unit"><input type="number" min="0" step="0.01" v-model.number="quote.extraCost"/><span>{{state.settings.currency==='GBP'?'£':state.settings.currency==='USD'?'$':'€'}}</span></div></div></div>
            <div class="info-box"><Info :size="17"/><span>Printer setup, post-processing, power consumption and machine overhead are pulled automatically from your printer profile.</span></div>
          </section>
          <section class="card result-card"><div class="card-heading"><div><h2>Cost breakdown</h2><p>A clear view of where every penny goes.</p></div><div class="card-badge">02 / RESULTS</div></div>
            <div class="breakdown"><div class="cost-row"><div><span class="cost-icon"><Layers3 :size="16"/></span>Filament <small>{{num(quote.grams)*calc.qty}}g total</small></div><strong>{{money(calc.material)}}</strong></div><div class="cost-row"><div><span class="cost-icon"><Zap :size="16"/></span>Electricity <small>{{printer?.power||0}} W</small></div><strong>{{money(calc.energy)}}</strong></div><div class="cost-row"><div><span class="cost-icon"><Clock3 :size="16"/></span>Labour <small>Setup + finishing</small></div><strong>{{money(calc.labour)}}</strong></div><div class="cost-row"><div><span class="cost-icon"><Printer :size="16"/></span>Machine overhead <small>Wear & maintenance</small></div><strong>{{money(calc.overhead)}}</strong></div><div class="cost-row"><div><span class="cost-icon"><Plus :size="16"/></span>Additional costs</div><strong>{{money(calc.extras)}}</strong></div></div>
            <div class="totals"><div><span>Production cost</span><strong>{{money(calc.cost)}}</strong></div><div><span>Profit ({{calc.margin}}% margin)</span><strong class="profit">+ {{money(calc.profit)}}</strong></div></div>
            <div class="grand-total"><div><span>RECOMMENDED SELLING PRICE</span><strong>{{money(calc.price)}}</strong><small>{{money(calc.unit)}} per item · {{calc.qty}} item{{calc.qty===1?'':'s'}}</small></div><TrendingUp :size="29"/></div>
            <p class="footnote">Profit margin = profit ÷ selling price. This differs from markup, which is profit ÷ cost. Prices exclude VAT and payment/platform fees unless added as extra costs.</p>
          </section>
        </div>
      </div>
      <div v-if="page==='filaments' && features.filaments"><div class="page-head"><div><div class="eyebrow">MATERIALS</div><h1>Filament library</h1><p>Keep your materials, cost per kilogram and supplier links in one place.</p></div><button class="btn primary" data-tour="tour-add-filament" @click="newFilament"><Plus :size="17"/> Add filament</button></div><div class="table-card"><div class="table-wrap"><table><thead><tr><th>FILAMENT</th><th>MATERIAL</th><th>COLOUR</th><th>PRICE / KG</th><th>SUPPLIER</th><th v-if="features.inventory">STOCK</th><th></th></tr></thead><tbody><tr v-for="f in state.filaments" :key="f.id"><td><strong>{{f.name}}</strong><small>{{f.brand||'Unbranded'}}</small></td><td><span class="tag">{{f.material}}</span></td><td>{{f.colour||'—'}}</td><td class="bold">{{money(f.price)}}</td><td><a v-if="f.url" :href="f.url" target="_blank" rel="noopener noreferrer" class="link">Buy filament <ExternalLink :size="13"/></a><span v-else class="muted">Not set</span></td><td v-if="features.inventory"><span :class="{'stock-low':num(f.stockGrams)<=num(f.lowStockGrams)}">{{num(f.stockGrams)}}g <span v-if="num(f.stockGrams)<=num(f.lowStockGrams)">· Low</span></span></td><td class="actions"><button class="btn small" @click="editFilament(f)">Edit</button><button class="icon-button danger" title="Delete" @click="removeFilament(f.id)"><Trash2 :size="16"/></button></td></tr><tr v-if="!state.filaments.length"><td :colspan="features.inventory?7:6" class="empty">No filaments yet. Add your first material to get started.</td></tr></tbody></table></div></div><div class="info-box page-info"><Info :size="17"/><span v-if="features.inventory">Track stock manually in each filament profile. Stock is not automatically deducted when recording sales.</span><span v-else>Enable optional stock tracking in Settings → Workspace features.</span></div></div>
      <div v-if="page==='printers' && features.printers"><div class="page-head"><div><div class="eyebrow">EQUIPMENT</div><h1>Printer profiles</h1><p>Configure a cost profile for every printer model you use.</p></div><button class="btn primary" data-tour="tour-add-printer" @click="newPrinter"><Plus :size="17"/> Add printer</button></div><div class="printer-grid"><div v-for="p in state.printers" :key="p.id" class="card printer-card"><div class="printer-top"><div class="printer-illustration"><Printer :size="27"/></div><span class="tag">{{p.technology}}</span></div><h2>{{p.name}}</h2><div class="printer-details"><div><span>Average power</span><strong>{{p.power}} W</strong></div><div><span>Setup time / job</span><strong>{{p.setupMinutes}} min</strong></div><div><span>Post-processing / item</span><strong>{{p.postMinutes}} min</strong></div><div><span>Machine overhead / hr</span><strong>{{money(p.overheadRate)}}</strong></div></div><div class="printer-actions"><button class="btn small" @click="editPrinter(p)">Edit profile</button><button class="icon-button danger" @click="removePrinter(p.id)"><Trash2 :size="16"/></button></div></div><button class="add-card" @click="newPrinter"><Plus :size="26"/><strong>Add printer profile</strong><span>Set up another machine</span></button></div></div>
      <div v-if="page==='history' && features.quotes"><div class="page-head"><div><div class="eyebrow">YOUR PROJECTS</div><h1>Saved quotes</h1><p>Review past estimates and reuse them for your next print.</p></div></div><div class="table-card"><div class="table-wrap"><table><thead><tr><th>PROJECT</th><th>DATE</th><th>PRINTER</th><th>PRODUCTION COST</th><th>SELLING PRICE</th><th>PROFIT</th><th></th></tr></thead><tbody><tr v-for="q in state.quotes" :key="q.id"><td><strong>{{q.name}}</strong><small>{{q.filament}}</small></td><td>{{new Date(q.date).toLocaleDateString('en-GB')}}</td><td>{{q.printer}}</td><td>{{money(q.result.cost)}}</td><td class="bold">{{money(q.result.price)}}</td><td class="profit bold">{{money(q.result.profit)}}</td><td class="actions"><button class="btn small" @click="loadQuote(q)">Load</button><button v-if="features.products" class="btn small" @click="productFromQuote(q)">Make product</button><button class="icon-button danger" @click="removeQuote(q.id)"><Trash2 :size="16"/></button></td></tr><tr v-if="!state.quotes.length"><td colspan="7" class="empty">No saved quotes yet. Create an estimate and click “Save quote”.</td></tr></tbody></table></div></div></div>
      <div v-if="page==='products' && features.products">
  <div class="page-head"><div><div class="eyebrow">YOUR CATALOGUE</div><h1>Products</h1><p>Keep finished designs and repeat orders separate from one-off quotes.</p></div><button class="btn primary" @click="newProduct"><Plus :size="17"/> Add product</button></div>
  <div class="product-grid"><article v-for="item in state.products" :key="item.id" class="card product-card"><div class="product-top"><div class="product-icon"><Package :size="22"/></div><span class="product-status">{{item.status||'Active'}}</span></div><h2>{{item.name}}</h2><p class="product-description">{{item.description||'No description yet'}}</p><div class="product-meta"><span v-if="item.customer">For {{item.customer}}</span><span v-if="item.sku">{{item.sku}}</span><span>{{state.filaments.find(f=>f.id===item.filamentId)?.name||'Filament not selected'}}</span><span>{{state.printers.find(p=>p.id===item.printerId)?.name||'Printer not selected'}}</span></div><div class="product-price"><small>Selling price</small><strong>{{money(item.price)}}</strong><small v-if="productCost(item)!==null">Live cost {{money(productCost(item))}} · {{productMargin(item)?.toFixed(1)}}% margin</small><small v-else>Assign a valid filament and printer to calculate cost</small></div><div class="product-popularity">{{productUnits(item)}} units sold</div><div class="product-actions"><button class="btn small" @click="loadProduct(item)">Cost</button><button v-if="features.quotes" class="btn small" @click="addQuoteProduct(item)">Add to quote</button><button class="btn small" v-if="features.sales" @click="beginSale(item)">Record sale</button><button class="btn small" @click="editingProduct=clone(item)">Edit</button><button class="icon-button danger" aria-label="Delete product" @click="removeProduct(item.id)"><Trash2 :size="16"/></button></div></article>
  <button class="add-card product-add" @click="newProduct"><Plus :size="28"/><strong>Add your first product</strong><span>Save a reusable design or client job</span></button></div>
</div>
<div v-if="page==='settings'"><div class="page-head"><div><div class="eyebrow">PREFERENCES</div><h1>Settings</h1><p>Set the rates used across all your cost estimates.</p></div></div><section class="card workspace-panel"><div class="card-heading"><div><h2>Workspace features</h2><p>Choose a simple calculator or enable the tools you actually need. Hidden pages keep their saved data.</p></div><Layers3 :size="21" class="muted"/></div><div class="preset-row"><button type="button" class="btn" @click="applyPreset('simple')">Calculator only</button><button type="button" class="btn" @click="applyPreset('pricing')">Product pricing</button><button type="button" class="btn" @click="applyPreset('full')">Full workspace</button></div><div class="feature-grid"><label v-for="item in [{id:'dashboard',title:'Dashboard',hint:'Overview and statistics'},{id:'quotes',title:'Saved quotes',hint:'Save and reuse estimates'},{id:'products',title:'Products',hint:'Catalogue and live costs'},{id:'filaments',title:'Filament library',hint:'Material pricing profiles'},{id:'printers',title:'Printer profiles',hint:'Power, labour and overhead'},{id:'sales',title:'Sales analytics',hint:'Sales logging and forecasts'},{id:'inventory',title:'Filament stock',hint:'Manual stock balances and low-stock alerts'}]" :key="item.id" class="feature-option"><div><strong>{{item.title}}</strong><small>{{item.hint}}</small></div><input type="checkbox" :checked="features[item.id]" @change="toggleFeature(item.id)" :aria-label="'Enable '+item.title"/></label></div><div class="info-box"><Info :size="17"/>The calculator and Settings are always available. Hiding a page never deletes its records. Filament and printer profiles still power costing when their pages are hidden.</div></section><section class="card branding-panel"><div class="card-heading"><div><h2>Appearance & branding</h2><p>Personalise the entire workspace. Changes appear instantly.</p></div><Settings2 :size="21" class="muted"/></div><div class="branding-grid"><div><div class="field"><label>Site title</label><input v-model="state.settings.siteTitle" maxlength="36" placeholder="PrintQuote"/></div><div class="field"><label>Subtitle / tagline</label><input v-model="state.settings.siteSubtitle" maxlength="50" placeholder="PRINT COST STUDIO"/></div><div class="field"><label>Logo image</label><div class="logo-picker"><div class="logo-preview"><img v-if="state.settings.logo" :src="state.settings.logo" alt="Logo preview"/><Box v-else :size="25"/></div><div><button class="btn small" @click="logoInput?.click()"><Upload :size="15"/> Upload logo</button><button v-if="state.settings.logo" class="btn small" @click="state.settings.logo=''">Remove</button><p class="hint">PNG, JPG, SVG or WebP · max 1 MB</p></div><input ref="logoInput" type="file" accept="image/*" hidden @change="uploadLogo"/></div></div></div><div><div class="field"><label>Accent colour</label><div class="colour-field"><input type="color" v-model="state.settings.accent"/><input v-model="state.settings.accent" aria-label="Accent colour hex" maxlength="7"/></div></div><div class="field"><label>Theme preference</label><select v-model="state.settings.themeMode"><option value="auto">Automatic (system)</option><option value="light">Light</option><option value="dark">Dark</option></select></div><div class="field"><label>Dark canvas colour</label><div class="colour-field"><input type="color" v-model="state.settings.darkBackground"/><input v-model="state.settings.darkBackground" maxlength="7"/></div></div><div class="field"><label>Light canvas colour</label><div class="colour-field"><input type="color" v-model="state.settings.background"/><input v-model="state.settings.background" aria-label="Background colour hex" maxlength="7"/></div></div><p class="appearance-note">A soft, layered canvas keeps your workspace calm and readable in both light and dark mode.</p><button class="btn small" @click="Object.assign(state.settings,{accent:'#5277e8',background:'#f3f7ff',darkBackground:'#1b283d',themeMode:'auto'})">Reset colours</button></div></div></section><div class="settings-layout"><section class="card"><div class="card-heading"><div><h2>Business rates</h2><p>Changes are saved automatically.</p></div><Settings2 :size="21" class="muted"/></div><div class="field"><label>Currency</label><select v-model="state.settings.currency"><option value="GBP">British Pound (£)</option><option value="EUR">Euro (€)</option><option value="USD">US Dollar ($)</option></select></div><div class="field"><label>Electricity price <span>per kWh</span></label><div class="input-unit"><input type="number" min="0" step="0.001" v-model.number="state.settings.energyRate"/><span>/ kWh</span></div></div><div class="field"><label>Labour rate <span>per hour</span></label><div class="input-unit"><input type="number" min="0" step="0.5" v-model.number="state.settings.labourRate"/><span>/ hr</span></div></div><div class="field"><label>Default margin <span>for new estimates</span></label><div class="input-unit"><input type="number" min="0" max="99.9" step="1" v-model.number="state.settings.defaultMargin" @change="quote.margin=state.settings.defaultMargin"/><span>%</span></div></div><div class="info-box"><Info :size="17"/>Electricity is calculated from average printer wattage × print duration × your kWh rate. Labour uses the setup and finishing times saved in each printer profile.</div></section><section class="card"><div class="card-heading"><div><h2>Your data</h2><p>Export or restore the shared workspace.</p></div><Download :size="21" class="muted"/></div><p class="secondary-text">Filaments, printers, branding, rates and saved quotes are stored in the built-in SQLite database and shared by every device accessing this server. You can also export a JSON backup.</p><div class="backup-actions"><button class="btn" @click="exportData"><Download :size="16"/> Export backup</button><button class="btn" @click="fileInput?.click()"><Upload :size="16"/> Import backup</button><input ref="fileInput" type="file" accept="application/json,.json" hidden @change="importData"/></div><div class="info-box"><Info :size="17"/>Browser storage is not used for application data. Back up the SQLite database file regularly. This deployment is intended for a trusted private network; add authentication before publishing it online.</div></section></div></div>
      <footer>PrintQuote <span>•</span> Built for makers, designed for clear pricing.</footer>
    </div>
  </main>
  <div v-if="tourActive && ready" class="tour-layer" aria-live="polite">
    <div class="tour-scrim"></div>
    <div class="tour-panel" :style="tourPosition" role="dialog" aria-modal="false" aria-labelledby="tour-title">
      <div class="tour-kicker"><Sparkles :size="16"/> LET'S GET STARTED <span>{{tourStep+1}} / {{tourSteps.length}}</span></div>
      <h2 id="tour-title">{{tourCurrent.title}}</h2><p>{{tourCurrent.body}}</p>
      <div class="tour-progress"><span v-for="(_,i) in tourSteps" :key="i" :class="{filled:i<=tourStep}"></span></div>
      <div class="tour-actions"><button class="btn small" @click="skipTour">Skip tour</button><button class="btn primary small" @click="tourStep===tourSteps.length-1?finishTour():nextTour()">{{tourStep===tourSteps.length-1?'Finish':'Next step'}} <ChevronRight :size="15"/></button></div>
      <small>You can click the highlighted control, or use Next step. Replay this tour anytime with the ? in the header.</small>
    </div>
  </div>
  <div v-if="saleProduct && features.sales" class="modal-backdrop" @click.self="saleProduct=null"><form class="modal" @submit.prevent="recordSale"><div class="modal-head"><div><h2>Record sale</h2><p>{{saleProduct.name}} · record an actual sale, not a quote</p></div><button type="button" class="icon-button" @click="saleProduct=null"><X :size="20"/></button></div><div class="field-grid"><div class="field"><label>Quantity sold</label><input required type="number" min="1" step="1" v-model.number="saleDraft.quantity"/></div><div class="field"><label>Sale price per item</label><input required type="number" min="0" step="0.01" v-model.number="saleDraft.unitPrice"/></div></div><div class="field"><label>Date</label><input required type="date" v-model="saleDraft.date"/></div><div class="field"><label>Notes (optional)</label><input v-model="saleDraft.note" placeholder="Order reference or customer"/></div><div class="info-box"><Info :size="16"/>The sale records its price and estimated unit cost today. Future material price changes won't rewrite your sales history.</div><div class="modal-actions"><button type="button" class="btn" @click="saleProduct=null">Cancel</button><button type="submit" class="btn primary">Record sale</button></div></form></div>
  <div v-if="notification" class="toast"><Check :size="17"/>{{notification}}</div>
  <div v-if="editingProduct" class="modal-backdrop" @click.self="editingProduct=null"><form class="modal" @submit.prevent="saveProduct"><div class="modal-head"><div><h2>Saved product</h2><p>Reusable design or client print</p></div><button type="button" class="icon-button" @click="editingProduct=null"><X :size="20"/></button></div><div class="field-grid"><div class="field"><label>Product name *</label><input required v-model="editingProduct.name" placeholder="e.g. Custom phone stand"/></div><div class="field"><label>SKU / reference</label><input v-model="editingProduct.sku" placeholder="Optional"/></div></div><div class="field"><label>Description</label><input v-model="editingProduct.description" placeholder="What is this product?"/></div><div class="field-grid"><div class="field"><label>Customer (optional)</label><input v-model="editingProduct.customer" placeholder="Client name"/></div><div class="field"><label>Status</label><select v-model="editingProduct.status"><option>Active</option><option>Archived</option><option>Prototype</option></select></div></div><div class="field-grid"><div class="field"><label>Filament</label><select v-model="editingProduct.filamentId"><option value="">Not selected</option><option v-for="f in state.filaments" :key="f.id" :value="f.id">{{f.name}}</option></select></div><div class="field"><label>Printer</label><select v-model="editingProduct.printerId"><option value="">Not selected</option><option v-for="p in state.printers" :key="p.id" :value="p.id">{{p.name}}</option></select></div></div><div class="field-grid"><div class="field"><label>Filament (g)</label><input type="number" min="0" step="0.1" v-model.number="editingProduct.grams"/></div><div class="field"><label>Saved selling price</label><input type="number" min="0" step="0.01" v-model.number="editingProduct.price"/></div></div><div class="field-grid"><div class="field"><label>Print hours</label><input type="number" min="0" step="1" v-model.number="editingProduct.hours"/></div><div class="field"><label>Print minutes</label><input type="number" min="0" step="1" v-model.number="editingProduct.minutes"/></div></div><div class="field"><label>Notes</label><input v-model="editingProduct.notes" placeholder="Finishing or production notes"/></div><div class="modal-actions"><button type="button" class="btn" @click="editingProduct=null">Cancel</button><button type="submit" class="btn primary">Save product</button></div></form></div>
<div v-if="editingFilament" class="modal-backdrop" @click.self="editingFilament=null"><form class="modal" @submit.prevent="saveFilament"><div class="modal-head"><div><h2>{{state.filaments.some(f=>f.id===editingFilament.id)?'Edit filament':'Add filament'}}</h2><p>Material pricing details</p></div><button type="button" class="icon-button" @click="editingFilament=null"><X :size="20"/></button></div><div class="field-grid"><div class="field"><label>Filament name *</label><input v-model="editingFilament.name" required placeholder="e.g. PLA Matte"/></div><div class="field"><label>Brand</label><input v-model="editingFilament.brand" placeholder="e.g. eSUN"/></div></div><div class="field-grid"><div class="field"><label>Material type</label><select v-model="editingFilament.material"><option v-for="m in ['PLA','PLA+','PETG','ABS','ASA','TPU','Nylon','PC','Other']" :key="m">{{m}}</option></select></div><div class="field"><label>Colour / variant</label><input v-model="editingFilament.colour" placeholder="e.g. Matte black"/></div></div><div class="field"><label>Price per kilogram</label><input type="number" min="0" step="0.01" v-model.number="editingFilament.price"/></div><div class="field"><label>Purchase link</label><input type="url" v-model="editingFilament.url" placeholder="https://..."/></div><div v-if="features.inventory" class="field-grid inventory-editor"><div class="field"><label>Stock remaining (g)</label><input type="number" min="0" step="1" v-model.number="editingFilament.stockGrams"/></div><div class="field"><label>Low stock warning (g)</label><input type="number" min="0" step="1" v-model.number="editingFilament.lowStockGrams"/></div></div><div class="modal-actions"><button type="button" class="btn" @click="editingFilament=null">Cancel</button><button class="btn primary" type="submit">Save filament</button></div></form></div>
  <div v-if="editingPrinter" class="modal-backdrop" @click.self="editingPrinter=null"><form class="modal" @submit.prevent="savePrinter"><div class="modal-head"><div><h2>{{state.printers.some(p=>p.id===editingPrinter.id)?'Edit printer':'Add printer'}}</h2><p>Printer-specific cost profile</p></div><button type="button" class="icon-button" @click="editingPrinter=null"><X :size="20"/></button></div><div class="field"><label>Printer model *</label><input v-model="editingPrinter.name" required placeholder="e.g. Bambu Lab P1S"/></div><div class="field-grid"><div class="field"><label>Technology</label><select v-model="editingPrinter.technology"><option>FDM</option><option>Resin</option><option>Other</option></select></div><div class="field"><label>Average power consumption (W)</label><input type="number" min="0" step="1" v-model.number="editingPrinter.power"/></div></div><div class="field-grid"><div class="field"><label>Setup time / job (min)</label><input type="number" min="0" step="1" v-model.number="editingPrinter.setupMinutes"/></div><div class="field"><label>Post-processing / item (min)</label><input type="number" min="0" step="1" v-model.number="editingPrinter.postMinutes"/></div></div><div class="field"><label>Machine overhead / print hour</label><input type="number" min="0" step="0.01" v-model.number="editingPrinter.overheadRate"/></div><div class="info-box"><Info :size="17"/>Machine overhead can account for wear, depreciation, servicing and consumables. Enter your own hourly estimate.</div><div class="modal-actions"><button type="button" class="btn" @click="editingPrinter=null">Cancel</button><button class="btn primary" type="submit">Save printer</button></div></form></div>
</div>
</template>
